package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class ScheduledTransactionService{private final LedgerRepository ledgers;private final ScheduledTransactionRepository schedules;private final AccountRepository accounts;public ScheduledTransactionService(LedgerRepository l,ScheduledTransactionRepository s,AccountRepository a){ledgers=l;schedules=s;accounts=a;}public Mono<ScheduledTransactionView> create(UUID a,UUID l,CreateScheduledTransactionRequest q){if(q.amount().signum()<=0)return Mono.error(new IllegalArgumentException("计划交易金额必须大于 0"));return own(a,l).flatMap(x->account(a,l,q.accountId()).flatMap(source->(q.type()==TransactionType.TRANSFER?account(a,l,q.targetAccountId()).then():Mono.empty()).then(schedules.save(new ScheduledTransactionEntity(null,l,a,q.rule(),q.nextRun(),q.type(),q.accountId(),q.targetAccountId(),q.amount(),q.currency()==null?source.currency():q.currency().toUpperCase(),q.categoryId(),q.payee(),q.note(),true,Instant.now(),Instant.now(),null))))).map(this::view);}public Flux<ScheduledTransactionView> list(UUID a,UUID l){return own(a,l).flatMapMany(x->schedules.findAllByLedgerIdAndOwnerIdOrderByNextRunAsc(l,a).map(this::view));}public Mono<ScheduledTransactionView> setActive(UUID a,UUID id,boolean active){return schedules.findById(id).filter(s->s.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Scheduled Transaction 不存在或无权访问"))).flatMap(s->schedules.save(new ScheduledTransactionEntity(s.id(),s.ledgerId(),s.ownerId(),s.rule(),s.nextRun(),s.type(),s.accountId(),s.targetAccountId(),s.amount(),s.currency(),s.categoryId(),s.payee(),s.note(),active,s.createdAt(),Instant.now(),s.version()))).map(this::view);}private Mono<LedgerEntity> own(UUID a,UUID l){return ledgers.findById(l).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private Mono<AccountEntity> account(UUID a,UUID l,UUID id){return accounts.findById(id).filter(x->x.ownerId().equals(a)&&x.ledgerId().equals(l)).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或不属于该 Ledger")));}private ScheduledTransactionView view(ScheduledTransactionEntity s){return new ScheduledTransactionView(s.id(),s.ledgerId(),s.rule(),s.nextRun(),s.type(),s.accountId(),s.targetAccountId(),s.amount(),s.currency(),s.categoryId(),s.payee(),s.note(),s.active());}}
